mod inventory {
    fn count() -> i32 { 6 }
    pub fn report() { println!("库存 {}", count()); }
}
fn main() { inventory::report(); }

mod catalog {
    pub mod printing {
        pub fn show() { println!("目录可见"); }
    }
}
fn main() { crate::catalog::printing::show(); }

fn announce() { println!("准备开始"); }
mod worker {
    pub fn run() {
        super::announce();
        println!("执行当前任务");
    }
}
fn main() { worker::run(); }

mod shop {
    pub struct Item { pub name: String, stock: i32 }
    impl Item {
        pub fn new() -> Item { Item { name: String::from("铅笔"), stock: 5 } }
        pub fn stock(&self) -> i32 { self.stock }
    }
    pub enum Kind { Paper, Tool }
}
fn main() {
    let item = shop::Item::new();
    let _kind = shop::Kind::Tool;
    println!("{} {}", item.name, item.stock());
}

mod work {
    pub mod tools {
        pub fn run() { println!("工具运行"); }
    }
}
use crate::work::tools;
fn main() {
    tools::run();
    tools::run();
}

mod storage { pub struct Item(pub i32); }
mod display { pub struct Item(pub i32); }
use crate::storage::Item as StoredItem;
use crate::display::Item as ShownItem;
fn main() {
    let stored = StoredItem(3);
    let shown = ShownItem(9);
    println!("{} {}", stored.0, shown.0);
}

mod internal {
    pub fn launch() { println!("启动公开功能"); }
}
pub use crate::internal::launch;
fn main() { launch(); }

use std::{cmp::Ordering, collections::HashMap};
fn main() {
    let mut values: HashMap<&str, i32> = HashMap::new();
    values.insert("长度", 4);
    let state = 4.cmp(&7);
    println!("{} {}", values.len(), state == Ordering::Less);
}

mod marks {
    pub const LOW: i32 = 2;
    pub const HIGH: i32 = 8;
    const INTERNAL: i32 = 99;
    pub fn internal_value() -> i32 { INTERNAL }
}
use crate::marks::*;
fn main() { println!("{} {}", LOW, HIGH); }

